{
  char name[30];
  int ni;

  printf("\nEnter your first name &gt; ");
  ni = scanf("%s",name);

  printf("\nHello %s!\n",name);

  return(0);
}
compile it with the following command line:
gcc -o hello2 hello2.c
and then run it with the following command:
